{
  // Čekaj da se DOM elementi učitaju
  await Promises.delay(200);

  // Sakrij sve grafikone
  const allCharts = document.querySelectorAll('.tax-wedge-chart');
  allCharts.forEach(chart =&gt; {
    chart.style.display = 'none';
  });

  // Prikaži odabrani grafikon
  const selectedChart = document.getElementById('chart-' + selectedType);
  if (selectedChart) {
    selectedChart.style.display = 'block';

    // Resize echarts ako postoji
    const echartsContainer = selectedChart.querySelector('[_echarts_instance_]');
    if (echartsContainer && window.echarts) {
      const instance = echarts.getInstanceByDom(echartsContainer);
      if (instance) {
        instance.resize();
      }
    }
  }
}








